CREATE TABLE `{prefix}ad_dim` (
  `id` bigint NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `type` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `{prefix}search_term_dim` (
  `id` bigint NOT NULL,
  `terms` varchar(255) DEFAULT NULL,
